		_Tp* __rval = static_cast<_Tp*>(__src->_M_addr());
		::new (__target._M_addr()) _Tp(std::move(*__rval));
		__rval->~_Tp();
	      }
	    else
	      static_cast<_Tp*>(__target._M_addr())->~_Tp();
