        EXPECT_TRUE(decltype(av.subspan<0, 5>())::extent == 5);
        EXPECT_TRUE(av.subspan(0, 5).size() == 5);

#ifdef CONFIRM_COMPILATION_ERRORS
        (void) av.subspan<0, 6>();
        (void) av.subspan<1, 5>();
#endif
        EXPECT_DEATH(av.subspan(0, 6), expected);
        EXPECT_DEATH(av.subspan(1, 5), expected);
    }

