        EXPECT_TRUE(decltype(av.subspan<5, 0>())::extent == 0);
        EXPECT_TRUE(av.subspan(5, 0).size() == 0);

#ifdef CONFIRM_COMPILATION_ERRORS
        (void) av.subspan<6, 0>();
#endif
        EXPECT_DEATH(av.subspan(6, 0), expected);
    }

    {
        span<int, 5> av = arr;
